<include file="Public:header"/><div class="mainbox">	<div id="nav" class="mainnav_title">		<ul>			<a href="{pigcms{:U('energy_package')}">能量包列表</a>|			<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('energy_package_add')}','添加套餐',600,500,true,false,false,addbtn,'add',true);">添加能量包</a>|			<a href="{pigcms{:U('energy_package_order')}" class="on">订单列表</a>		</ul>	</div>    <table class="search_table" width="100%">        <tr>            <td>                <form action="{pigcms{:U('Recruit/energy_package_order')}" method="get">                    <input type="hidden" name="c" value="Recruit"/>                    <input type="hidden" name="a" value="energy_package_order"/>                    筛选: <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>                    <select name="type">                        <option value="name" <if condition="$_GET['type'] eq 'name'">selected="selected"</if>>能量包名</option>                        <option value="nickname" <if condition="$_GET['type'] eq 'nickname'">selected="selected"</if>>用户昵称</option>                        <option value="phone" <if condition="$_GET['type'] eq 'phone'">selected="selected"</if>>用户手机号</option>                    </select>                    <input type="submit" value="查询" class="button"/>                </form>            </td>        </tr>    </table>	<form name="myform" id="myform" action="" method="post">		<div class="table-list">			<table width="100%" cellspacing="0">				<colgroup>					<col/>					<col/>					<col/>					<col/>					<col/>					<col/>					<col/>					<col/>					<col/>					<col/>					<col  align="center"/>				</colgroup>				<thead>					<tr>						<th>编号</th>						<th>能量包名</th>						<th>金额</th>						<th>用户名</th>						<th>手机号</th>						<th>订单创建时间</th>						<th>订单支付时间</th>						<th>支付方式</th>						<th>状态</th>						<th>操作</th>					</tr>				</thead>				<tbody>					<if condition="$list['list']">						<volist name="list.list" id="vo">							<tr>								<td>{pigcms{$vo.order_id}</td>								<td>{pigcms{$vo.name}</td>								<td>{pigcms{$vo.price}</td>								<td>{pigcms{$vo.nickname}</td>								<td>{pigcms{$vo.phone}</td>								<td><if condition="$vo['order_time']">{pigcms{$vo.order_time|date='Y-m-d H:i:s',###}</if></td>								<td><if condition="$vo['paid'] eq 1">{pigcms{$vo.pay_time|date='Y-m-d H:i:s',###}<else/>未支付</if></td>								<td><if condition="$vo['pay_type']">{pigcms{$vo.pay_type}<else/>余额支付</if></td>								<td>                                <if condition="$vo['paid'] eq 0">                                	<span style="color: orange;">未支付</span>                                <elseif condition="$vo['paid'] eq 1"/>                                	<span style="color: green;">已支付</span>                                </if>                            	</td>								<td>									<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('energy_package_order_detail',array('order_id'=>$vo['order_id']))}','订单详情',600,500,true,false,false,editbtn,'',true);">查看详情</a>							  	</td>							</tr>						</volist>						<tr><td class="textcenter pagebar" colspan="20">{pigcms{$list.pagebar}</td></tr>					<else/>						<tr><td class="textcenter red" colspan="20">列表为空！</td></tr>					</if>				</tbody>			</table>		</div>	</form></div><include file="Public:footer"/>